metadata.er-schema:
{
  "title": "looply · 翻译模块 实体关系图",
  "version": "v2.0 · 2026-05-17",
  "tables": [
    {
      "name": "language",
      "comment": "语言",
      "columns": [
        {
          "name": "language_code",
          "comment": "语言代码（如en/fr/de）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "language_name",
          "comment": "语言名称（英文）",
          "constraint": ""
        },
        {
          "name": "language_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "rtl",
          "comment": "是否从右到左",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 639-1 作主键，外部引用（归属 Market 模块管理）"
    },
    {
      "name": "translation_request",
      "comment": "翻译请求",
      "columns": [
        {
          "name": "request_id",
          "comment": "请求ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型",
          "constraint": ""
        },
        {
          "name": "resource_id",
          "comment": "资源ID",
          "constraint": ""
        },
        {
          "name": "resource_name",
          "comment": "资源显示名（冗余，避免反查业务模块）",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_text",
          "comment": "源文本内容",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源文本哈希",
          "constraint": ""
        },
        {
          "name": "source_version",
          "comment": "源内容版本号",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（pending/processing/completed/cancelled）",
          "constraint": ""
        }
      ],
      "note": "业务模块推送的翻译请求队列（翻译模块的收件箱）。业务模块在资源创建/变更时主动推送，翻译模块被动消费"
    },
    {
      "name": "translation",
      "comment": "翻译内容",
      "columns": [
        {
          "name": "translation_id",
          "comment": "翻译ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（开放字段，由业务模块注册）",
          "constraint": ""
        },
        {
          "name": "resource_id",
          "comment": "资源ID",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translated_value",
          "comment": "翻译内容",
          "constraint": ""
        },
        {
          "name": "translation_source",
          "comment": "翻译来源（manual/ai/vendor）",
          "constraint": ""
        },
        {
          "name": "source_version",
          "comment": "源内容版本号",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源内容哈希",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（pending_review/approved/outdated）",
          "constraint": ""
        },
        {
          "name": "reviewed_by",
          "comment": "审核人",
          "constraint": ""
        },
        {
          "name": "reviewed_at",
          "comment": "审核时间",
          "constraint": ""
        }
      ],
      "note": "EAV 单表，每条记录是当前有效版本（不保留历史版本）。唯一性：resource_type+resource_id+field_name+source_language_code+language_code"
