      "note": "任务内单条翻译条目，独立携带资源定位信息，支持首次翻译（translation 行尚不存在）。translation_id 为完成后回填字段（可空）"
    },
    {
      "name": "glossary_concept",
      "comment": "术语概念",
      "columns": [
        {
          "name": "concept_id",
          "comment": "概念ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_term",
          "comment": "源术语",
          "constraint": ""
        },
        {
          "name": "rule_type",
          "comment": "规则类型（do_not_translate/mandatory/recommended）",
          "constraint": ""
        },
        {
          "name": "context",
          "comment": "使用场景说明",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "术语管理的核心实体，一个概念对应一个源词。rule_type 决定翻译约束强度"
    },
    {
      "name": "glossary_translation",
